fn drain_batch_from_queue(queue: &mut VecDeque<QueueEntry>, group_commit_enabled: bool) -> Vec<QueueEntry> {
    if group_commit_enabled {
        queue.drain(..).collect()
    } else {
        let mut one = VecDeque::new();
        if let Some(entry) = queue.pop_front() {
            one.push_back(entry);
        }
        one.into()
    }
}

